import numpy as np
from qiskit import QuantumCircuit
from qiskit.quantum_info import DensityMatrix, Statevector

# The five states MUST mirror data/figures/s1-q052/generate.py — the rendered
# figures are plot_state_city drawings of exactly these states, and a city plot
# IS the density matrix (real part in the left panel, imaginary in the right).


def state(*gates):
    qc = QuantumCircuit(2)
    for name, *args in gates:
        getattr(qc, name)(*args)
    return Statevector(qc)


def stem_state():
    return state(("h", 0), ("cx", 0, 1), ("s", 1))


VARIANTS = {
    "A": state(("h", 0), ("cx", 0, 1), ("sdg", 1)),
    "B": stem_state(),
    "C": state(("h", 0), ("cx", 0, 1), ("z", 1)),
    "D": state(("h", 0), ("h", 1), ("s", 1)),
    "E": state(("h", 0), ("cx", 0, 1)),
}


def drawn(st):
    """What plot_state_city puts on its two panels: Re(rho) and Im(rho)."""
    rho = np.round(DensityMatrix(st).data, 6)
    return (tuple(map(tuple, rho.real.tolist())), tuple(map(tuple, rho.imag.tolist())))


def describe(bars):
    re, im = bars
    n_re = sum(1 for row in re for v in row if abs(v) > 1e-9)
    n_im = sum(1 for row in im for v in row if abs(v) > 1e-9)
    corner = re[0][3]
    corner_i = im[0][3]
    return (f"real panel has {n_re} non-zero bars, imaginary panel has {n_im}; "
            f"the |00><11| cell is {corner:+.2f} real / {corner_i:+.2f} imaginary")


target = drawn(stem_state())
proven, evidence, observed = [], {}, {}
for key, st in sorted(VARIANTS.items()):
    bars = drawn(st)
    match = bars == target
    observed[key] = describe(bars)
    evidence[key] = (
        f"figure: {describe(bars)}; the stem code draws {describe(target)} -> match={match}"
    )
    if match:
        proven.append(key)

observed["stem"] = describe(target)
emit_verdict({"answer": proven, "evidence": evidence, "observed": observed})
